package cn.medreminder.app;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Build;
import java.util.*;

public final class Alarms {
 public static final String MED_ID="medId", REVISION="revision", PLANNED_AT="plannedAt", OCCURRENCE="occurrence";
 private static final String PREF="alarm_state", CHANNEL="medication_reminders";
 private Alarms() {}
 public static final class SlotPlan { public final Set<String> cancel,schedule; SlotPlan(Set<String> c,Set<String> s){cancel=c;schedule=s;} }
 public static SlotPlan reconcileSlots(Set<String> existing,Set<String> desired){Set<String> cancel=new HashSet<>(existing);cancel.removeAll(desired);return new SlotPlan(cancel,new HashSet<>(desired));}
 public static Set<String> slotsToSchedule(Set<String> desired,Set<String> persisted){return new HashSet<>(desired);}
 public static Map<String,String> pendingByMed(Store s,Set<String> existing){Map<String,String> pending=new HashMap<>();Map<String,Long> times=new HashMap<>();for(String key:existing){String[] a=key.split(":",3);try{if(a.length==3){long id=Long.parseLong(a[0]),rev=Long.parseLong(a[1]),at=Long.parseLong(a[2]);String med=Long.toString(id);if(mayDeliver(s,id,rev,key,at)&&(!times.containsKey(med)||at<times.get(med))){pending.put(med,key);times.put(med,at);}}}catch(Exception ignored){}}return pending;}
 private static boolean handled(Store s,Store.Med m,long at){String key=Core.occurrence(m.id,m.revision,at);return s.forOccurrence(key)!=null||s.isSkipped(key);}
 public static long nextUnconfirmed(Store s,Store.Med med,String hhmm,long now,String zone){long at=Core.nextTime(hhmm,now,zone);while(handled(s,med,at))at=Core.nextTime(hhmm,at,zone);return at;}
 public static long nextFrequencyUnconfirmed(Store s,Store.Med med,long now,String zone){long at=Core.nextFrequency(med.anchor,med.frequencyDays,med.frequencyCount,now,zone);while(handled(s,med,at))at=Core.nextFrequency(med.anchor,med.frequencyDays,med.frequencyCount,at,zone);return at;}
 public static long nextForMed(Store s,Store.Med med,long now,String zone){if(med.scheduleMode.equals(Store.FREQUENCY))return nextFrequencyUnconfirmed(s,med,now,zone);long best=Long.MAX_VALUE;for(String t:Core.normalizeTimes(med.times).split(",")){long at=nextUnconfirmed(s,med,t,now,zone);if(at<best)best=at;}return best;}
 public static boolean mayDeliver(Store s,long med,long revision,String key,long plannedAt){if(key==null||plannedAt<=0||!Core.occurrence(med,revision,plannedAt).equals(key)||s.forOccurrence(key)!=null||s.isSkipped(key))return false;Store.Med m=s.med(med);return m!=null&&m.active&&m.revision==revision;}
 private static PendingIntent alarmPi(Context c,long med,long rev,long at,String key,int flags){
  Intent i=new Intent(c,ReminderReceiver.class).setAction("cn.medreminder.app.REMIND").setData(new Uri.Builder().scheme("medreminder").authority("slot").appendPath(key).build());
  i.putExtra(MED_ID,med);i.putExtra(REVISION,rev);i.putExtra(PLANNED_AT,at);i.putExtra(OCCURRENCE,key);
  return PendingIntent.getBroadcast(c,0,i,flags|PendingIntent.FLAG_IMMUTABLE);
 }
 public static void reschedule(Context context){reschedule(context,"ui");}
 public static void reschedule(Context context,String reason){
  AlarmSelfTest.reschedule(context,reason);
  Context c=context.getApplicationContext(); Store s=new Store(c); List<Store.Med> meds=s.meds(true); SharedPreferences p=c.getSharedPreferences(PREF,0);
  Map<String,Long> revisions=new HashMap<>(); long now=System.currentTimeMillis(); Set<String> existing=new HashSet<>();
  for(String k:p.getAll().keySet())if(k.startsWith("slot:"))existing.add(k.substring(5));
  Map<String,String> pendingByMed=pendingByMed(s,existing);
  Set<String> desired=new HashSet<>(); Map<String,Long> atByKey=new HashMap<>();
  for(Store.Med m:meds){revisions.put(Long.toString(m.id),m.revision);try{String pending=pendingByMed.get(Long.toString(m.id));long at;if(pending!=null){at=Long.parseLong(pending.split(":",3)[2]);desired.add(pending);atByKey.put(pending,at);}else{at=nextForMed(s,m,now,TimeZone.getDefault().getID());String key=Core.occurrence(m.id,m.revision,at);desired.add(key);atByKey.put(key,at);}}catch(RuntimeException failure){diag(p,"last_alarm_result","plan_failed");}}
  p.edit().putLong("last_intended_at",atByKey.isEmpty()?0:Collections.min(atByKey.values())).apply();
  AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE); SlotPlan plan=reconcileSlots(existing,desired);
  for(String key:plan.cancel){String[] a=key.split(":",3);try{long id=Long.parseLong(a[0]),rev=Long.parseLong(a[1]),at=Long.parseLong(a[2]);PendingIntent pi=alarmPi(c,id,rev,at,key,PendingIntent.FLAG_NO_CREATE);if(pi!=null){am.cancel(pi);pi.cancel();}}catch(Exception ignored){}p.edit().remove("slot:"+key).apply();}
  boolean exact=Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms();
  for(String key:plan.schedule){try{String[] a=key.split(":",3);long id=Long.parseLong(a[0]),rev=Long.parseLong(a[1]),at=Long.parseLong(a[2]);PendingIntent pi=alarmPi(c,id,rev,at,key,PendingIntent.FLAG_UPDATE_CURRENT);String result=schedule(am,at,pi,exact,c);diag(p,"last_alarm_mode",result);diag(p,"last_alarm_result",result.equals("failed")?"registration_failed":"registered");p.edit().putLong("last_alarm_registered_at",at).apply();if(!result.equals("failed"))p.edit().putBoolean("slot:"+key,true).apply();else p.edit().remove("slot:"+key).apply();}catch(RuntimeException failure){diag(p,"last_alarm_result","registration_failed");}}
  Map<String,Long> prior=new HashMap<>();for(String k:p.getAll().keySet())if(k.startsWith("med:")){try{prior.put(k.substring(4),p.getLong(k,-1));}catch(Exception ignored){}}
  for(String id:prior.keySet())if(!revisions.containsKey(id)||!revisions.get(id).equals(prior.get(id)))cancelMedicationNotices(c,id,revisions.get(id));
  SharedPreferences.Editor e=p.edit();for(String id:revisions.keySet())e.putLong("med:"+id,revisions.get(id));for(String id:prior.keySet())if(!revisions.containsKey(id))e.remove("med:"+id);e.apply();
  retryBlockedNotices(c,s,p);
 }
 private static void retryBlockedNotices(Context c,Store s,SharedPreferences p){for(String pref:new HashSet<>(p.getAll().keySet()))if(pref.startsWith("retry:")){String key=pref.substring(6);String[] a=key.split(":",3);try{long id=Long.parseLong(a[0]),rev=Long.parseLong(a[1]),at=Long.parseLong(a[2]);boolean eligible=mayDeliver(s,id,rev,key,at),enabled=notificationsEnabled(c,(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE));if(!eligible){p.edit().remove(pref).apply();continue;}if(NotificationRetry.shouldRetry(eligible,enabled))post(c,s.med(id),id,rev,key,at);}catch(Exception ignored){p.edit().remove(pref).apply();}}}
 private static void diag(SharedPreferences p,String key,String value){p.edit().putString(key,value).apply();}
 private static String schedule(final AlarmManager am,final long at,final PendingIntent pi,boolean exact,final Context c){return AlarmClockRegistration.register(exact,new AlarmClockRegistration.Registrar(){public void alarmClock(){Intent show=new Intent(c,MainActivity.class).setAction("cn.medreminder.app.SHOW_ALARM").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);PendingIntent showPi=PendingIntent.getActivity(c,0x4d4544,show,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);am.setAlarmClock(new AlarmManager.AlarmClockInfo(at,showPi),pi);}public void exactIdle(){am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);}public void inexact(){am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);}});}
 public static void delivered(Context c,long med,long revision,String occurrence,long plannedAt){SharedPreferences state=c.getSharedPreferences(PREF,0);state.edit().putLong("last_receiver_at",System.currentTimeMillis()).apply();Store s=new Store(c);SharedPreferences p=c.getSharedPreferences(PREF,0);p.edit().remove("slot:"+occurrence).apply();reschedule(c,"receiver");if(!mayDeliver(s,med,revision,occurrence,plannedAt))return;Store.Med m=s.med(med);if(c.getSharedPreferences(PREF,0).getBoolean("notice:"+occurrence,false))return;post(c,m,med,revision,occurrence,plannedAt);}
 private static void channel(Context c){if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel(CHANNEL,c.getString(R.string.notification_channel_name),NotificationManager.IMPORTANCE_DEFAULT);ch.setLockscreenVisibility(Notification.VISIBILITY_PRIVATE);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(ch);}}
 private static void markRetry(SharedPreferences p,String key){SharedPreferences.Editor e=p.edit();for(String pref:p.getAll().keySet())if(pref.startsWith("retry:"))e.remove(pref);e.putBoolean("retry:"+key,true).apply();}
 private static void post(Context c,Store.Med m,long id,long rev,String key,long at){try{channel(c);NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(!notificationsEnabled(c,nm)){SharedPreferences state=c.getSharedPreferences(PREF,0);state.edit().putString("last_notify_result","blocked_notifications_disabled").apply();markRetry(state,key);return;}Intent open=new Intent(c,MainActivity.class).putExtra(MED_ID,id).putExtra(REVISION,rev).putExtra(PLANNED_AT,at).putExtra(OCCURRENCE,key).setData(Uri.parse("medreminder://open/"+Uri.encode(key)));PendingIntent content=PendingIntent.getActivity(c,(key+"open").hashCode(),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
  Intent confirm=new Intent(c,ConfirmReceiver.class).setData(Uri.parse("medreminder://confirm/"+Uri.encode(key))).putExtra(MED_ID,id).putExtra(REVISION,rev).putExtra(PLANNED_AT,at).putExtra(OCCURRENCE,key);confirm.setClass(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent action=PendingIntent.getActivity(c,(key+"confirm").hashCode(),confirm,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
  Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);b.setSmallIcon(R.drawable.ic_stat_notification).setContentTitle(c.getString(R.string.alarm_notification_title)).setContentText(m.name+" · "+m.dose).setVisibility(Notification.VISIBILITY_PRIVATE).setAutoCancel(true).setContentIntent(content).addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_save,c.getString(R.string.alarm_record_action),action).build());String result=NotificationSubmission.submit(notificationsEnabled(c,nm),new NotificationSubmission.Submitter(){public void submit(){nm.notify(key.hashCode(),b.build());}});SharedPreferences state=c.getSharedPreferences(PREF,0);state.edit().putString("last_notify_result",result).apply();if(result.equals("submitted_to_os"))state.edit().putBoolean("notice:"+key,true).remove("retry:"+key).apply();else markRetry(state,key);}catch(RuntimeException denied){SharedPreferences state=c.getSharedPreferences(PREF,0);state.edit().putString("last_notify_result","notify_failed").apply();markRetry(state,key);}} public static void cancelNotice(Context c,String occurrence){((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(occurrence.hashCode());c.getSharedPreferences(PREF,0).edit().remove("notice:"+occurrence).remove("retry:"+occurrence).apply();}
 private static void cancelMedicationNotices(Context c,String id,Long activeRevision){SharedPreferences p=c.getSharedPreferences(PREF,0);for(String k:new HashSet<>(p.getAll().keySet()))if(k.startsWith("notice:")||k.startsWith("retry:")){String key=k.substring(k.indexOf(':')+1);String[] parts=key.split(":",3);try{if(parts.length>=2&&parts[0].equals(id)&&(activeRevision==null||Long.parseLong(parts[1])!=activeRevision))cancelNotice(c,key);}catch(Exception ignored){}}}
 private static boolean notificationsEnabled(Context c,NotificationManager nm){boolean app=Build.VERSION.SDK_INT<24||nm.areNotificationsEnabled();boolean runtime=Build.VERSION.SDK_INT<33||c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")==android.content.pm.PackageManager.PERMISSION_GRANTED;boolean channel=true;if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=nm.getNotificationChannel(CHANNEL);channel=ch!=null&&ch.getImportance()!=NotificationManager.IMPORTANCE_NONE;}return NotificationAvailability.enabled(app,runtime,channel);}
 private static String localizedCode(Context c,String code){int id;
  if("alarm_clock".equals(code))id=R.string.self_test_mode_alarm_clock;else if("exact_idle".equals(code))id=R.string.self_test_mode_exact_idle;else if("inexact".equals(code))id=R.string.self_test_mode_inexact;else if("registered".equals(code)||"exact".equals(code)||"fallback".equals(code))id=R.string.alarm_registered;else if("registration_failed".equals(code)||"failed".equals(code))id=R.string.alarm_registration_failed;else if("plan_failed".equals(code))id=R.string.alarm_plan_failed;else if("notify_failed".equals(code))id=R.string.alarm_notification_failed;else if("submitted_to_os".equals(code))id=R.string.self_test_notice_submitted;else if("blocked_notifications_disabled".equals(code))id=R.string.self_test_notice_blocked;else if("not_attempted".equals(code))id=R.string.alarm_never;else id=R.string.alarm_code_unknown;return c.getString(id);}
 public static String status(Context c){channel(c);NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);boolean enabled=notificationsEnabled(c,nm);boolean exact=Build.VERSION.SDK_INT<31||((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).canScheduleExactAlarms();String battery=c.getString(R.string.alarm_battery_unknown);if(Build.VERSION.SDK_INT>=23){android.os.PowerManager pm=(android.os.PowerManager)c.getSystemService(Context.POWER_SERVICE);battery=c.getString(pm.isIgnoringBatteryOptimizations(c.getPackageName())?R.string.alarm_exempt:R.string.alarm_not_exempt_system);}return c.getString(R.string.alarm_status,c.getString(enabled?R.string.alarm_enabled:R.string.alarm_disabled),c.getString(exact?R.string.alarm_available:R.string.alarm_unavailable),battery);}
 public static String diagnostics(Context c){SharedPreferences p=c.getSharedPreferences(PREF,0);long intended=p.getLong("last_intended_at",0),registered=p.getLong("last_alarm_registered_at",0),receiver=p.getLong("last_receiver_at",0);String intendedText=intended>0?new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.ROOT).format(new Date(intended)):c.getString(R.string.alarm_never);String registeredText=registered>0?new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.ROOT).format(new Date(registered)):c.getString(R.string.alarm_never);String receiverText=receiver>0?new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.ROOT).format(new Date(receiver)):c.getString(R.string.alarm_never);return c.getString(R.string.alarm_diagnostics,intendedText,registeredText,localizedCode(c,p.getString("last_alarm_mode","")),localizedCode(c,p.getString("last_alarm_result","")),receiverText,localizedCode(c,p.getString("last_notify_result","")));}

 public static void requestExact(Activity a){if(Build.VERSION.SDK_INT>=31)try{a.startActivity(new Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+a.getPackageName())));}catch(Exception unavailable){android.widget.Toast.makeText(a,a.getString(R.string.alarm_exact_settings_unavailable),android.widget.Toast.LENGTH_LONG).show();}}
 public static void requestNotifications(Activity a){try{if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED){a.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},3401);return;}a.startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,a.getPackageName()));}catch(RuntimeException unavailable){android.widget.Toast.makeText(a,a.getString(R.string.alarm_request_notification_fallback),android.widget.Toast.LENGTH_LONG).show();}}
 public static void test(Context c){try{channel(c);NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);NotificationChannel ch=nm.getNotificationChannel(CHANNEL);if(!nm.areNotificationsEnabled()||(ch!=null&&ch.getImportance()==NotificationManager.IMPORTANCE_NONE)){android.widget.Toast.makeText(c,c.getString(R.string.alarm_test_blocked),android.widget.Toast.LENGTH_LONG).show();return;}Notification.Builder b=new Notification.Builder(c,CHANNEL);nm.notify(0x4d4544,b.setSmallIcon(R.drawable.ic_stat_notification).setContentTitle(c.getString(R.string.alarm_test_title)).setContentText(c.getString(R.string.alarm_test_text)).setVisibility(Notification.VISIBILITY_PRIVATE).build());}catch(RuntimeException denied){android.widget.Toast.makeText(c,c.getString(R.string.alarm_test_failed),android.widget.Toast.LENGTH_LONG).show();}}
}
